                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
          },
          onSubagentStart: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentText: (data) => {
            subagentTextBufRef.current[data.id] = (subagentTextBufRef.current[data.id] || '') + data.text;
            if (!subagentFlushRef.current) {
              subagentFlushRef.current = setTimeout(() => {
                flushSubagentText();
                subagentFlushRef.current = null;
              }, 50);
            }
          },
          onSubagentEnd: (data) => {
            if (subagentFlushRef.current) {
              clearTimeout(subagentFlushRef.current);
              subagentFlushRef.current = null;
            }
            flushSubagentText();
            if (data.chart_spec) {
              segmentsRef.current.push({
                type: 'subagent_end',
                subagentId: data.id,
                subagentName: data.name,
                chart_spec: data.chart_spec,
              });
            } else if (data.result) {
              const hasStreamed = segmentsRef.current.some(
                (s) => s.type === 'answer' && s.subagentId === data.id
              );
              if (!hasStreamed) {
                segmentsRef.current.push({
                  type: 'answer',
                  text: data.result,
                  subagentId: data.id,
                });
              }
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (subagentFlushRef.current) {
              clearTimeout(subagentFlushRef.current);
              subagentFlushRef.current = null;
            }
            flushSubagentText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({
                type: 'answer',
                text: currentTextRef.current,
              });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
